// Retrieve and parse the environment and global variables
const eventCodes = env.get("EVENT_CODES");
const waterStands = env.get("WATER_STANDS");
const thresholdWaterLevel = env.get("WATER_LEVEL_THRESHOLD");
const validModes = env.get("AWT_MODES");
const standStatus = global.get("WATER_STANDS_STATUS");
const frClientApi = env.get("FR_API_CLIENT_ID");
const awsMode = env.get("AWS_MODES");

let truck = msg.truck;
let truckName = msg.truckName;
let waterStandName = msg.waterStand;
let currentTime = Date.now();

let status = {
    failed : false,
    ready: true,
    reason: 0
}

// Retrieve the current awsStatus from global context
let awsStatus = global.get("awsStatus") || {}; // Initialize to an empty object if it doesn't exist

let currMode = awsStatus?.[waterStandName]?.[truckName]?.mode ?? null; 
let failed = awsStatus?.[waterStandName]?.[truckName]?.awtStatus?.failed ?? null;

// Define the criteria for water refill
let isModeCorrect = validModes.includes(truck.AutonomousTruckMode);
let isSpeedZero = truck.Speed === 0;
let isWaterLevelLow = parseInt(thresholdWaterLevel) > truck.WaterLevel;
let isTruckAtSpot = truck.TruckAtSpotPoint === "true";
let isInGeofence = false;

// Find the water stand based on the message
let waterStand = waterStands.find(element => element.name === waterStandName);

if (!waterStand) {
    // Handle case where no matching water stand is found
    status.ready = false;
    status.reason = eventCodes.FAULTS.MISSING_CONFIGURATIONS;
}
//dont waste time checking states if your state is failed 
else if (failed)  {
    status.ready = awsStatus[waterStandName][truckName].awtStatus.ready;
    status.failed = awsStatus[waterStandName][truckName].awtStatus.failed;
    status.reason = awsStatus[waterStandName][truckName].awtStatus.reason;
}
//this is the case where you check all the states again
else {
    // Get the PLC and API status from the standStatus object
    let plcStatus = standStatus[waterStandName]?.plcStatus;
    let apiStatus = standStatus[waterStandName]?.apiStatus;

    // First, check the PLC status
    if (plcStatus.reason !== eventCodes.PLC.HEALTHY) {
        // if (plcStatus.healthy) {
        status.ready = plcStatus.healthy;
        status.reason = plcStatus.reason;
        status.failed = true;
        msg.status = status;
    }
    // Then, check the API status
    else if (apiStatus.reason !== eventCodes.API.HEALTHY) {
        // if (apiStatus.healthy) {
        status.ready = apiStatus.healthy;
        status.reason = apiStatus.reason;
        msg.status = status;
    }
    // Check if the truck is stationary (speed = 0)
    else if (!isSpeedZero) {
        status.ready = false;
        status.reason = eventCodes.AWT.NOT_STATIONARY;
    }
    // Check if the truck is in the correct mode
    else if (!isModeCorrect) {
        status.ready = false;
        status.reason = eventCodes.AWT.MODE_INCORRECT;
    }
    // Only check the geofence if the AWT is stationary
    else {
        const { geofence } = waterStand;
        if (geofence) {
            isInGeofence =
                Number(truck.CoordinateX) < geofence.maxX &&
                Number(truck.CoordinateX) > geofence.minX &&
                Number(truck.CoordinateY) < geofence.maxY &&
                Number(truck.CoordinateY) > geofence.minY;

            // Update status based on position check
            if (!isInGeofence) {
                status.ready = false;
                status.reason = eventCodes.FAULTS.MISALIGNED;
            }
        }
    }
    if (currMode && currMode === "DETECTED" && !isWaterLevelLow) {
        status.ready = false;
        status.reason = eventCodes.AWT.WATER_LEVEL_HIGH;
    }
}

// Initialize or update truck entry with status and status

msg.awtStatus = {  // Embed AWT status information
                    isModeCorrect: isModeCorrect,
                    isSpeedZero: isSpeedZero,
                    isWaterLevelLow: isWaterLevelLow,
                    isTruckAtSpot: isTruckAtSpot,
                    isInGeofence: isInGeofence
                    };

msg.status = status;


// // Return the modified message
return msg;

