    previousMode = awsStatus[waterStandName][truckName].mode;
    //the status.failed flag will not reset for a truck if its true once
    //so basically if a truck has faulted once and it has failed then you cannot bring that truck back have to kick it out
    if (previousMode !== "COMPLETED") {
        if (msg.status.failed && previousMode === "FAULT") {
        }
        else {
            if (!msg.status.ready) {
                newMode = "FAULT";
            }
            else if (msg.status.ready) {
                // Update the mode if nextMode is defined
                if (nextMode) {
                    // node.warn(`Updating truck: ${truckName} to next mode: ${nextMode}`);
                    newMode = nextMode;
                } else {
                    if (previousMode == "FAULT") {
                        newMode = "DETECTED";
                    }
                }
            }
        }
    }
}

// Update the current mode based on the latest status in awsStatus
msg.previousMode = previousMode; // Capture the previous mode
msg.newMode = newMode ? newMode : awsStatus[waterStandName][truckName].mode;

// Return the modified message
