// Input:   msg.payload.heartbeat
// Output:  msg.payload { isHealthy: boolean }
// Env:     PLC_DISCONNECT_TIMEOUT (ms) - max elapsed time without a heartbeat change before reporting unhealthy
// Notes:   Heartbeat is an INT (0–9999) that increments each PLC scan and wraps back to 0.
//          State is held in node context, so each node instance tracks its own heartbeat independently.

//const timeoutMs = Number(env.get("PLC_DISCONNECT_TIMEOUT")) || 5000;
const timeoutMs = 50;
const currentHB = Number(msg.payload.heartbeat);
const now = Date.now();

const lastHB = context.get("lastHeartbeat");
let lastSeen = context.get("lastHeartbeatSeen") ?? now;

if (currentHB !== lastHB) {
    context.set("lastHeartbeat", currentHB);
    context.set("lastHeartbeatSeen", now);
    lastSeen = now;
}

const isHealthy = now - lastSeen < timeoutMs;

if (isHealthy) {
    node.status({ fill: "green", shape: "dot", text: "healthy" });
} else {
    node.status({ fill: "red", shape: "ring", text: "disconnected" });
}

msg.payload = { isHealthy, lastUpdate: lastSeen };
return msg;

