// Purpose: Check if this API client holds a motion lock on each AWS in the payload.
// Input:   msg.payload (array) - validated array of 1–5 AWS objects
// Output:  msg.payload         - same array, entries with MotionStopOwnerList gain MotionLocked

const clientId = env.get("FR_API_CLIENT_ID");

