// Purpose: Store validated AWS location data into the global wsRead object.
// Input:   msg.payload (array) - validated AWS objects with MotionLocked appended
// Output:  global.wsRead - object keyed by LocationName, values keep the API payload format

const awsStatus = global.get("wsRead") ?? {};

function normalizeAwsLocation(aws) {
  if (aws.TruckName) {
    return aws;
  }

  return {
    LocationName: aws.LocationName,
    TruckName: "",
    CoordinateX: 0,
    CoordinateY: 0,
    AutonomousTruckMode: "",
    WaterLevel: 0,
    Speed: 0,
    TruckAtSpotPoint: false,
    MotionStopOwnerList: [],
    MotionLocked: false,
  };
}

msg.payload.forEach((aws) => {
  const location = aws.LocationName;

  if (!location) {
    return;
  }

  awsStatus[location] = {
    ...normalizeAwsLocation(aws),
    lastUpdatedFromAPI: Date.now(),
  };
});

global.set("wsRead", awsStatus);

return msg;

// Purpose: Allow only decoded AWS records for enabled standpipe assets.
// Input:   msg.payload (object[]) - decoded AWS data from "Decode Modbus Registers.js"
//          global.sysConfig       - asset config array with name and Enable fields
// Output:  msg.payload (object[]) - enabled standpipe records only

const awsPayload = msg.payload;
const sysConfig = global.get("sysConfig") ?? [];

const enabledStandpipes = new Set(
    sysConfig
        .filter((asset) => asset.Enable === "TRUE")
        .map((asset) => asset.name),
);

msg.payload = awsPayload.filter((aws) =>
    enabledStandpipes.has(aws.Standpipe ?? aws.LocationName)
);

return msg;

