// Purpose: Summarise a flow's node status messages into one flow health value.
// Input:   msg from a Node-RED Status node, with msg.status and msg.source.
// Output:  msg.payload = { timestamp, status }
// Notes:   Health is also written to global.sysStatus.Flow[flowName].isHealthy.

const nodeStatuses = context.get("nodeStatuses") || {};
const now = Date.now();
const flowName = env.get("FLOW_NAME");

const sourceId = msg.status?.source?.id;
const statusFill = (msg.status?.fill || "").toLowerCase();

nodeStatuses[sourceId] = {
    fill: statusFill,
    lastUpdate: now,
};

context.set("nodeStatuses", nodeStatuses);

const hasFault = Object.values(nodeStatuses).some(
    (nodeStatus) => nodeStatus.fill === "red",
);
const summaryIsHealthy = !hasFault;
const summary = summaryIsHealthy ? "healthy" : "unhealthy";

const sysStatus = global.get("sysStatus") || {};
sysStatus.Flow ??= {};
sysStatus.Flow[flowName] ??= {};
sysStatus.Flow[flowName].isHealthy = summaryIsHealthy;
sysStatus.Flow[flowName].lastUpdate = now;
global.set("sysStatus", sysStatus);

msg.payload = {
    lastUpdate: now,
    status: summary,
};

msg.flowName = flowName;

return msg;

// Purpose: Summarise all flow health messages into one combined Node-RED status.
// Input:   msg.flowName - source flow name
//          msg.payload.status - flow status, expected "healthy" or "unhealthy"
// Output:  msg.payload = { timestamp, status } - emitted only when combined status changes
// Notes:   Previous flow statuses and last combined status are stored in this Function node context.

const flowName = msg.flowName;
const flowStatus = String(msg.payload?.status || "").toLowerCase();
const now = Date.now();

if (!flowName || !flowStatus) {
    return null;
}

const flowStatuses = context.get("flowStatuses") || {};

flowStatuses[flowName] = {
    status: flowStatus,
    lastUpdated: Date.now(),
};

context.set("flowStatuses", flowStatuses);

// Combined status is unhealthy when any remembered flow is not healthy.
const hasFault = Object.values(flowStatuses).some(
    (flow) => flow.status !== "healthy",
);
const summary = hasFault ? "unhealthy" : "healthy";


msg.payload = {
    timestamp: now,
    status: summary,
};

return msg;

