// Purpose: Record exit time and emit one pending record for database insertion.
// Input:   msg.payload.standpipe
// Output:  msg.payload - completed or partial record, emitted once

const standpipe = msg.payload?.standpipe;
const records = flow.get("awsUtilisationRecords") ?? {};
const record = records[standpipe];

if (!record) {
    return null;
}

const now = new Date().toISOString();

record.Exit_Time = now;

msg.payload = { ...record };

delete records[standpipe];
flow.set("awsUtilisationRecords", records);

return msg;

// Purpose: Start or replace the pending utilisation record for one standpipe.
// Input:   msg.payload { standpipe, skidId, eventCode }
// Global:  global.wsRead[standpipe].TruckName
// Storage: flow.awsUtilisationRecords

const awsPayload = msg.payload ?? {};
const standpipe = awsPayload.standpipe;

if (!standpipe) {
    return null;
}

const wsRead = global.get("wsRead") ?? {};
const awtID = wsRead[standpipe]?.TruckName || null;
const records = flow.get("awsUtilisationRecords") ?? {};
const now = new Date().toISOString();

records[standpipe] = {
    standpipe,
    Skid_ID: awsPayload.skidId || null,
    AWT_ID: awtID,
    Entry_Time: now,
    Start_Time: null,
    Start_Level: null,
    End_Time: null,
    End_Level: null,
    Exit_Time: null,
    Exit_Status: null,
    Fill_Volume: null,
};

flow.set("awsUtilisationRecords", records);
return null;

// Purpose: Capture fill start time and water level for a pending record.
// Input:   msg.payload.standpipe
// Global:  global.wsRead[standpipe].WaterLevel

const standpipe = msg.payload?.standpipe;
const records = flow.get("awsUtilisationRecords") ?? {};
const record = records[standpipe];

if (!record) {
    return null;
}

const waterLevel = global.get("wsRead")?.[standpipe]?.WaterLevel;
const now = new Date().toISOString();

record.Start_Time = now;
record.Start_Level = waterLevel;

flow.set("awsUtilisationRecords", records);
return null;

// Purpose: Capture or overwrite fill end time and water level for a pending record.
// Input:   msg.payload.standpipe
// Global:  global.wsRead[standpipe].WaterLevel

const standpipe = msg.payload?.standpipe;
const records = flow.get("awsUtilisationRecords") ?? {};
const record = records[standpipe];

if (!record) {
    return null;
}

const waterLevel = global.get("wsRead")?.[standpipe]?.WaterLevel;
const now = new Date().toISOString();

record.End_Time = now;
record.End_Level = waterLevel;

flow.set("awsUtilisationRecords", records);
return msg;

// Purpose: Record the first terminal reason for a pending record.
// Input:   msg.payload { standpipe, eventCode }, msg.terminalStatus
// Notes:   msg.terminalStatus is assigned by the upstream Change node.

const standpipe = msg.payload?.standpipe;
const records = flow.get("awsUtilisationRecords") ?? {};
const record = records[standpipe];

if (!record) {
    return null;
}

if (record.Exit_Status === null) {
    record.Exit_Status = msg.exitStatus;
}

flow.set("awsUtilisationRecords", records);
return null;

// Purpose: Calculate fill volume for a completed utilisation record.
// Input:   msg.payload.standpipe

const standpipe = msg.payload?.standpipe;
const records = flow.get("awsUtilisationRecords") ?? {};
const record = records[standpipe];

if (!record) {
    return null;
}

const startLevel = record.Start_Level;
const endLevel = record.End_Level;

record.Fill_Volume =
    startLevel === null || endLevel === null
        ? 0
        : endLevel - startLevel;

flow.set("awsUtilisationRecords", records);
return msg;

