// Purpose: Simulate a node status event for testing Check Node Status.js
// Input:   msg.payload (string) - "fault" triggers red error indicator, "healthy" triggers green status indicator
// Output:  msg shaped as a Node-RED status node event (msg.source + msg.status)

if (msg.payload === "fault") {
    node.error("Simulated fault");
    node.status({ fill: "red", shape: "dot", text: "error" });
} else if (msg.payload === "healthy") {
    node.status({ fill: "green", shape: "dot", text: "OK" });
} else {
    node.warn(`Unrecognised payload "${msg.payload}" — expected "fault" or "healthy"`);
    return null;
}

msg.source = {
    id: "sim-node-001",
    name: "Simulated Node",
    type: "function",
};

msg.status = {
    fill: msg.payload === "fault" ? "red" : "green",
    text: msg.payload === "fault" ? "error" : "OK",
};

return msg;

